import{_ as o,a0 as p,w as l,s as r,ao as d,I as i,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"我是如何使用 Linux fmt 命令來格式化文本 | LCTT x X-CMD","titleTemplate":false,"description":"我是如何使用 Linux fmt 命令來格式化文本 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我是如何使用 Linux fmt 命令來格式化文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我是如何使用 Linux fmt 命令來格式化文本 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220721 How I use the Linux fmt command to format text","title":"我是如何使用 Linux fmt 命令來格式化文本","tag":"202208","desc":""},"relativePath":"202208/20220721 How I use the Linux fmt command to format text.md","filePath":"[post].md"}'),h={name:"202208/20220721 How I use the Linux fmt command to format text.md"};function c(f,e,m,g,u,k){const t=p("Link");return l(),r("div",null,[e[15]||(e[15]=d(`<h1 id="我是如何使用-linux-fmt-命令來格式化文本" tabindex="-1">我是如何使用 Linux fmt 命令來格式化文本 <a class="header-anchor" href="#我是如何使用-linux-fmt-命令來格式化文本" aria-label="Permalink to “我是如何使用 Linux fmt 命令來格式化文本”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/01/184300zbyfjayeyqa5pmcb.jpg" alt=""></p><blockquote><p>fmt 命令是一個簡單的文本格式化程序。我將在這裏展示如何使用它來格式化文本和郵件回覆。</p></blockquote><p>當我為項目編寫文檔時，我經常以純文本的形式編寫自述文件和安裝説明。我不需要使用 HTML 或者 Markdown 之類的標記語言來描述項目的功能或如何編譯它。但是維護這樣的文檔可能會很痛苦。如果我需要更新我的 <code>Readme</code> 文件中的一個句子的中間位置，我需要重新格式化文本，以避免在我的其它文本中間出現一個很長或很短的行，而其它的行的格式是整整齊齊的 75 列。一些編輯器包含可以自動重新格式化文本以填充段落的功能，但並非所有的編輯器都這樣做。這就是 Linux <code>fmt</code> 命令的用武之地。</p><h3 id="使用-linux-fmt-命令格式化文本" tabindex="-1">使用 Linux fmt 命令格式化文本 <a class="header-anchor" href="#使用-linux-fmt-命令格式化文本" aria-label="Permalink to “使用 Linux fmt 命令格式化文本”">​</a></h3><p><code>fmt</code> 命令是一個簡單的文本格式化程序；它收集單詞並填充段落，但不應用任何其它文本樣式，例如斜體或粗體。這一切都是純文本。使用 <code>fmt</code> 命令，你可以快速調整文本，使其更易於閲讀。讓我們從這個熟悉的示例文本開始:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat trek.txt </span></span>
<span class="line"><span>Space: the final</span></span>
<span class="line"><span>frontier. These are the voyages</span></span>
<span class="line"><span>of the starship Enterprise. Its</span></span>
<span class="line"><span>continuing mission: to explore</span></span>
<span class="line"><span>strange new worlds. To</span></span>
<span class="line"><span>seek out new life and new</span></span>
<span class="line"><span>civilizations. To boldly go</span></span>
<span class="line"><span>where no one has gone before!</span></span></code></pre></div><p>在這個實例文件中，每行都有不同的長度，並且它們以一種奇怪的方式換行。如果你對純文本文件進行大量更改，你可以會遇到類似的奇怪的換行。要重新格式化此文本，你可以使用 <code>fmt</code> 命令將段落的行填充為統一長度：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fmt trek.txt </span></span>
<span class="line"><span>Space: the final frontier. These are the voyages of the starship</span></span>
<span class="line"><span>Enterprise. Its continuing mission: to explore strange new worlds. To</span></span>
<span class="line"><span>seek out new life and new civilizations. To boldly go where no one has</span></span>
<span class="line"><span>gone before!</span></span></code></pre></div><p>默認情況下，<code>fmt</code> 會將文本格式化為 75 的列寬大小，但你可以使用 <code>-w</code> 或 <code>--width</code> 選項進行更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fmt -w 60 trek.txt </span></span>
<span class="line"><span>Space: the final frontier. These are the voyages of</span></span>
<span class="line"><span>the starship Enterprise. Its continuing mission: to</span></span>
<span class="line"><span>explore strange new worlds. To seek out new life and new</span></span>
<span class="line"><span>civilizations. To boldly go where no one has gone before!</span></span></code></pre></div><h3 id="使用-linux-fmt-命令格式化電子郵件回覆" tabindex="-1">使用 Linux fmt 命令格式化電子郵件回覆 <a class="header-anchor" href="#使用-linux-fmt-命令格式化電子郵件回覆" aria-label="Permalink to “使用 Linux fmt 命令格式化電子郵件回覆”">​</a></h3><p>我加入了一個郵件列表，這裏更喜歡純文本電子郵件，這使得在列表服務器上歸檔電子郵件變得更加容易。但現實是並非每個人都以純文本形式發送電子郵件。有時候，當我以純文本形式回覆這些電子郵件時，我的電子郵件客户端會將整個段落放在一行中。這使得在電子郵件中“引用”回覆變得困難。</p><p>這是一個簡單的例子。當我以純文本形式回覆電子郵件時，我的電子郵件客户端通過在每行前添加 <code>&gt;</code> 字符來“引用”對方的電子郵件。對於一條短消息，可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; I like the idea of the interim development builds.</span></span></code></pre></div><p>沒有正確“換行”的長行將無法在我的純文本電子郵件回覆中正確顯示，因為它只是前面帶有 <code>&gt;</code> 字符的長行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; I like the idea of the interim development builds. This should be a great way to test new changes that everyone can experiment with.</span></span></code></pre></div><p>為了解決這個問題，我打開了一個終端並將引用的文本複製並粘貼到一個新文件中。然後我使用 <code>-p</code> 或 <code>--prefix</code> 選項來告訴 <code>fmt</code> 在每一行之前使用什麼字符作為“前綴”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &gt; email.txt</span></span>
<span class="line"><span>&gt; I like the idea of the interim development builds. This should be a great way to test new changes that everyone can experiment with.</span></span>
<span class="line"><span>^D</span></span>
<span class="line"><span>$ fmt -p &#39;&gt;&#39; email.txt</span></span>
<span class="line"><span>&gt; I like the idea of the interim development builds. This should be a</span></span>
<span class="line"><span>&gt; great way to test new changes that everyone can experiment with.</span></span></code></pre></div><p><code>fmt</code> 命令是一個非常簡單的文本格式化程序，但它可以做很多有用的事情，可以幫助以純文本形式編寫和更新文檔。要了解其它選項，例如 <code>-c</code> 或 <code>--crown-margin</code> 以匹配段落前兩行縮進，例如項目列表。還可以嘗試使用 <code>-t</code> 或者 <code>--tagged-paragraph</code> 來保留段落中第一行的縮進，就像縮進的段落一樣。<code>-u</code> 或 <code>--uniform-spacing</code> 選項在單詞之間使用一個空格，在句子之間使用兩個空格。</p><hr>`,21)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensource.com/article/22/7/fmt-trivial-text-formatter"},{default:n(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/22/7/fmt-trivial-text-formatter",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensource.com/users/jim-hall"},{default:n(()=>[...e[2]||(e[2]=[s("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(t,{href:"https://github.com/perfiffer"},{default:n(()=>[...e[4]||(e[4]=[s("perfiffer",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const T=o(h,[["render",c]]);export{w as __pageData,T as default};
